"""Build the 20-adventure editorial catalogue; base five routes remain stable."""
import json, math
from pathlib import Path
root = Path(__file__).resolve().parent.parent
file = root / 'assets/data/catalog.json'
d = json.loads(file.read_text())
d['routes'] = d['routes'][:5]
d['places'] = d['places'][:30]
P = {p['id']: p for p in d['places']}
S = {
'yeldegirmeni':'https://goturkiye.com/istanbul/kadikoy',
'uskudar':'https://en.wikipedia.org/wiki/%C3%9Csk%C3%BCdar',
'cukurcuma':'https://en.wikipedia.org/wiki/%C3%87ukurcuma',
'cihangir':'https://en.wikipedia.org/wiki/Cihangir',
'besiktas':'https://en.wikipedia.org/wiki/Be%C5%9Fikta%C5%9F',
'ortakoy':'https://goturkiye.com/istanbul/ortakoy',
'emirgan':'https://goturkiye.com/istanbul/emirgan-park',
'gulhane':'https://visit.istanbul/gulhane-park',
'salt':'https://saltonline.org/en/visit?tag=26',
'gazhane':'https://muzegazhane.istanbul/ziyaret/',
'sirkeci':'https://en.wikipedia.org/wiki/Sirkeci_railway_station',
'caddebostan':'https://en.wikipedia.org/wiki/Caddebostan'}
def point(name,address,lat,lon,context,notice,mission,region,category='Городские детали',indoors=False):
    id=f'p{len(d["places"]):02}'
    image=f'assets/images/{region}.jpg'
    if not (root / image).exists(): image='assets/images/city.jpg'
    suffix = ('Выберите одну доступную посетителям деталь и рассмотрите её спокойно. Не заходите в служебные помещения. Если раздел временно закрыт или идёт монтаж, остановку можно заменить: конкретную выставку и открытый зал приложение не гарантирует.' if indoors else 'Оставайтесь на общедоступной стороне улицы или парковой дорожке. Не нужно заходить в частный двор, занимать чужое крыльцо или покупать что-либо ради отметки. Если тесно, выберите точку чуть в стороне и сохраните наблюдение словами.')
    story=context+'\n\n'+notice+' '+suffix+'\n\nВ личном атласе можно оставить одну фразу о том, что удивило именно сегодня. Задание добровольное; продолжайте, когда будете готовы.'
    p=dict(id=id,name=name,category=category,image=image,imageCaption='Реальная фотография Стамбула; не обязательно этой остановки.',address=address+', İstanbul, Türkiye',lat=lat,lon=lon,coordinateAccuracy='Ориентир, а не точная отметка входа; внутри здания используется общий адрес.',story=story,notice=notice,tryIt=mission+'. Достаточно наблюдения; покупка не требуется.',mission=mission,missionType='Наблюдать',missionDetails=notice,hours='В светлое время суток; режим территории и текущие ограничения уточняйте на месте.',visitMinutes=10,cost='Базовое действие без покупки. Транспорт и необязательный перекус отдельно.',access='Покрытие, пороги и доступность требуют проверки на месте; безбарьерность не подтверждена.',booking='Для наружного осмотра запись не нужна. Посещение мероприятий и закрытых пространств в маршрут не входит.',sources=[S[region]],checkedAt='2026-10-22',verification='Контекст сверён с указанным источником. Координаты, переходы и время — редакционные оценки.')
    if indoors:
        p.update(hours='Вт–сб 11:00–19:00, вс 11:00–18:00, пн закрыто. Возможны праздничные закрытия и монтаж.',cost='Вход в Salt бесплатный; покупки в книжном магазине и кафе необязательны.',booking='Обычный визит без обязательного билета. Программа и доступные залы зависят от текущей работы площадки.')
    d['places'].append(p);P[id]=p;return id

def group(region,category,rows,indoors=False):
    return [point(*row,region,category,indoors) for row in rows]

def route(name,desc,theme,mood,ids,minutes,maxMinutes,region,area,transport,practical,stairs='unknown',indoor=False,last=16,earliest=8,food=(10000,40000),stopMinutes=10,hints=None,closed=None):
    edges={}
    for aid in ids:
        for bid in ids:
            if aid==bid:continue
            a,b=P[aid],P[bid];x,y=math.radians(a['lat']),math.radians(b['lat']);dl=math.radians(b['lon']-a['lon'])
            direct=6371000*2*math.asin(math.sqrt(math.sin((y-x)/2)**2+math.cos(x)*math.cos(y)*math.sin(dl/2)**2))
            m=max(30,round((direct*1.35+(10 if indoor else 30))/25)*25)
            edges[aid+'|'+bid]=dict(meters=m,minutes=max(1,math.ceil(m/65)),features='Оценка перехода по ориентировочным координатам. Уточните безопасный проход на месте и в картах; внутри здания следуйте указателям площадки.')
    a,b,end=ids[:3];lengths=[sum(edges[k]['meters'] for k in [a+'|'+b,b+'|'+c,c+'|'+end]) for c in ids[3:5]]
    meter=min(lengths);image=P[ids[0]]['image']
    r=dict(id=f'r{len(d["routes"])}',name=name,description=desc,theme=theme,mood=mood,image=image,minutes=minutes,maxMinutes=maxMinutes,meters=meter,requiredMin=0,requiredMax=0,foodMin=food[0],foodMax=food[1],stairs=stairs,lastStart=last,earliestStart=earliest,family=True,indoor=indoor,rest=True,diets=['Вегетарианское','Веганское','Без алкоголя'],places=ids[:3],branches=ids[3:5],alternative=ids[5],legs=[edges[a+'|'+b]['meters'],edges[b+'|'+ids[3]]['meters'],edges[ids[3]+'|'+end]['meters']],branchDelta=[dict(minutes=0,meters=lengths[0]-meter,cost=0),dict(minutes=5,meters=lengths[1]-meter,cost=0)],branchHints=[dict(title=h[0],description=h[1]) for h in (hints or [('Линии и формы','Рассмотреть детали и найти собственный ракурс.'),('Цвета и настроение','Выбрать палитру и сохранить маленькую историю.')])],missionIndices=[0,1,2],transitions=edges,area=area,gettingThere=transport,practical=practical,stopMinutes=stopMinutes,closedWeekdays=closed or [],overview='Две общие остановки, один выбранный вариант и финал. Есть запасная точка; места открываются по ходу.',budgetNote=f'Базовые задания без обязательных покупок. Перекус по желанию: ориентировочно {food[0]//100}–{food[1]//100} ₺ на человека, не прайс конкретного заведения. Доезд и покупки отдельно. Пищевые предпочтения не означают сертификацию меню.',distanceNote='Время включает короткие паузы, длина рассчитана приблизительно по координатам. Полевой проверки не было. Обходы, монтаж и выбранная ветка меняют путь.',sources=list(dict.fromkeys(u for id in ids for u in P[id]['sources'])),checkedAt='2026-10-22')
    d['routes'].append(r)

